<?php foreach(['forms'=>['Forms, landing pages and surveys',['visitors','responses','confirmed','conversion_rate'],'collection-report'],'flows'=>['Automation performance',['runs','completed','exited','failed','active','completion_rate'],'flow-report']]as$dataset=>[$title,$columns,$destination]):$rows=$store->analyticsReportRows($window,['dataset'=>$dataset]); ?>
<section class="analytics-card"><header><h2><?= $h($title) ?></h2><?php if($canManage): ?><a href="<?= $h($reportLink(['download'=>$dataset])) ?>">Export data</a><?php endif; ?></header><?php $renderReportTable($rows,$columns,$dataset==='forms'?'Form':'Automation',$destination); ?><p class="analytics-explanation"><?php if($dataset==='forms'): ?>Daily unique visitors count a visitor again on a different day. Submissions and confirmed subscriptions are separate native records. Confirmation may occur after the visit window, so the ratio is observational and can exceed 100%. There is no inferred external purchase or cross-site attribution.<?php else: ?>Runs are grouped by their start date; completion and active status reflect their current outcome. Prior-period runs have had longer to finish. Open a flow to inspect the exact run and step evidence.<?php endif; ?></p></section>
<?php endforeach; ?>
